window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['bigdata-5']={"round":5,"cert":"bigdata","questions":[{"id":"6a6a00571bbde79cd2c72a87","number":1,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 개인정보 비식별화 기법인 총계처리(Aggregation)에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"개인정보 비식별화가 불가능하다."},{"n":2,"html":"데이터 전체가 비슷한 특성을 지닌 개인들로 이루어진 경우, 데이터의 대푯값이 특정 개인의 정보를 드러낼 우려가 있다."},{"n":3,"html":"세부 기법으로는 데이터 라운딩, 부분총계, 재배열 방법 등이 있다."},{"n":4,"html":"개인정보를 보호하기 위하여 데이터의 총합이나 평균값을 활용한다."}],"answer":[1],"explain":{"mine":"<p>총계처리는 합계·평균 등으로 개별 값을 감추는 <b>대표적인 비식별화 기법</b>입니다. '비식별화가 불가능하다'는 1번이 옳지 않습니다. 구성원이 모두 비슷하면 대푯값이 개인을 드러낼 수 있다는 한계(2번), 세부 기법(라운딩·부분총계·재배열)은 맞는 설명입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a85","number":2,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 빅데이터 분석을 위한 개인정보 처리 방법에 대한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"다른 정보와 결합하여 재식별되지 않도록 필수적인 관리 조치를 이행한다."},{"n":2,"html":"비식별 정보를 제공하거나 혹은 위탁한 자가 재식별 가능성을 발견한 경우 정보 처리자에게 즉시 통지하여 정보의 회수 및 파기 조치한다."},{"n":3,"html":"가명처리된 개인정보는 공익적 기록 보존을 위해 개인의 동의 없이 사용이 가능하다."},{"n":4,"html":"데이터 처리 과정 중 개인정보가 재식별되는 경우 즉시 파기하거나 추가적인 비식별 조치를 시행한다."}],"answer":[2],"explain":{"mine":"<p>가이드라인상 비식별 정보를 <b>제공받거나 위탁받은 자</b>가 재식별 가능성을 발견하면 즉시 처리를 중단하고 제공한 자에게 통지해 회수·파기 절차를 밟아야 합니다. 2번은 통지·조치의 주체가 뒤바뀐 서술이라 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a83","number":3,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 데이터 변환 기법에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"평활화(Smoothing) : 데이터 통합을 목적으로 새로운 속성이나 특징을 추가"},{"n":2,"html":"정규화(Normalization) : 최소-최대 정규화, Z-score 정규화 등의 통계적 기법을 데이터에 적용"},{"n":3,"html":"데이터 집계(Data Aggregation) : 여러 차원의 방식을 활용하여 데이터를 요약"},{"n":4,"html":"변수 변환(Variable Transformation) : y=f(x) 형태의 함수를 변수 값에 일괄적으로 적용하여 새로운 변수를 생성"}],"answer":[1],"explain":{"mine":"<p>평활화(Smoothing)는 <b>노이즈를 제거해 데이터를 매끄럽게</b> 만드는 기법입니다. '데이터 통합을 위해 새로운 속성을 추가한다'는 1번은 속성 생성·통합에 대한 설명이므로 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a86","number":4,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>개인정보 비식별화 조치에 관한 설명 가운데 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"총계처리(Aggregation) - 개인정보 데이터 값을 전부 합산하거나 평균값 등을 활용함"},{"n":2,"html":"가명처리(Pseudonymization) - 개인정보 중 식별 가능한 값을 다른 값으로 바꿈"},{"n":3,"html":"데이터 마스킹(Data Masking) - 개인정보의 식별 가능한 값이 드러나지 않도록 처리함"},{"n":4,"html":"범주화(Suppression) - 주요 개인 식별 정보의 일부를 삭제함"}],"answer":[4],"explain":{"mine":"<p>범주화(Categorization)는 값을 <b>범주나 구간으로 바꾸는</b> 기법(예: 33세→30대)이고, 주요 식별 정보의 일부를 삭제하는 것은 <b>데이터 삭제(Suppression)</b> 기법입니다. 용어와 설명의 짝이 어긋난 4번이 답입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a89","number":5,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>병렬 DBMS에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"다중 중앙처리장치와 디스크를 병렬로 활용하여 데이터 처리와 입출력 속도를 향상시킨다."},{"n":2,"html":"일반적으로 Massive Parallel Processing 구조를 가지며, 대량의 데이터를 신속하게 적재하고 저장한다."},{"n":3,"html":"데이터 적재, 색인 빌드, 쿼리 평가 등 여러 동작에 병렬 컴퓨팅을 적용하여 성능을 높인다."},{"n":4,"html":"순차 처리 방식의 DBMS에 비해 데이터 중복이 발생할 가능성이 높다."}],"answer":[4],"explain":{"mine":"<p>병렬 DBMS는 여러 CPU·디스크로 처리를 나누는 구조일 뿐, 순차 처리 DBMS보다 <b>데이터 중복이 더 발생하는 것은 아닙니다</b>(4번이 옳지 않음). MPP 구조, 병렬 적재·색인·쿼리 처리 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a84","number":6,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래와 같은 특징을 지닌 변수 변환 방법으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>정의역은 양수(Positive Real Number)로 한정된다.</li><li>공역은 모든 실수(Real Number)를 포함한다.</li><li>변환된 값은 제약식이 없는 실수이다.</li><li>정의역이 취하는 값의 범위에 따라 변환값의 최댓값과 최솟값 간 차이가 크게 나타난다.</li></ul></div>","choices":[{"n":1,"html":"자연로그 변환"},{"n":2,"html":"시계열 단위 변환"},{"n":3,"html":"구간화 변환"},{"n":4,"html":"평활 변환"}],"answer":[1],"explain":{"mine":"<p>정의역이 양수로 한정되고 공역이 모든 실수이며, 큰 값을 강하게 압축하는 변환은 <b>자연로그 변환</b>입니다(1번). ln(x)는 x&gt;0에서만 정의되고 결과는 음수부터 양수까지 모든 실수를 가질 수 있습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a7f","number":7,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석은 도메인 이슈 도출 → 분석 목표 수립 → 프로젝트 계획 수립 → 보유 데이터 자산 확인 → 분석결과 시각화 순서의 절차를 거쳐 진행된다. 다음 중 WBS(Work Breakdown Structure, 작업분할구조도)를 작성하는 단계는 어느 것인가?</p>","choices":[{"n":1,"html":"보유 데이터 자산 확인"},{"n":2,"html":"도메인 이슈 도출"},{"n":3,"html":"프로젝트 계획 수립"},{"n":4,"html":"분석 목표 수립"}],"answer":[3],"explain":{"mine":"<p>WBS(작업분할구조도)는 일정·산출물·담당을 정의하는 문서로 <b>프로젝트 계획 수립</b> 단계에서 작성합니다(3번).</p>"}},{"id":"6a6a00571bbde79cd2c72a8a","number":8,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래 보기에서 설명하는 특징에 해당하는 플랫폼 구조로 가장 적절한 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서버, 스토리지, 네트워크 등 자원의 사용을 지원</li><li>클라우드 서비스를 제공</li><li>서버 가상화, 데스크톱 가상화 등 자원관리 모듈을 지원</li></ul></div>","choices":[{"n":1,"html":"서비스형 자원관리 플랫폼"},{"n":2,"html":"서비스형 소프트웨어 플랫폼"},{"n":3,"html":"서비스형 인프라스트럭처 플랫폼"},{"n":4,"html":"서비스형 가상화 플랫폼"}],"answer":[3],"explain":{"mine":"<p>서버·스토리지·네트워크 <b>자원 자체를 서비스로 제공</b>하고 가상화 자원관리를 지원하는 것은 <b>서비스형 인프라스트럭처(IaaS)</b> 플랫폼입니다(3번). 소프트웨어를 제공하면 SaaS, 개발 환경을 제공하면 PaaS입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a7c","number":9,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>수집된 데이터를 테스트하고 데이터 수집이 가능한지 확인하기 위해서는 사전에 원천 데이터를 이해하고 탐색하는 과정이 요구된다. 이와 같은 업무가 수행되는 단계로 옳은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"분석 평가 및 전개"},{"n":2,"html":"데이터 분석"},{"n":3,"html":"분석결과 시각화"},{"n":4,"html":"도메인 이슈 도출"}],"answer":[2],"explain":{"mine":"<p>이 문제의 절차 구분에서 원천 데이터를 이해·탐색하고 수집 가능성을 테스트하는 업무는 <b>데이터 분석 단계</b>(분석을 위한 데이터 준비 작업 포함)에서 수행됩니다(2번). 도메인 이슈 도출은 업무 현황 파악, 시각화는 결과 표현 단계입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a79","number":10,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>인공지능, 머신러닝, 딥러닝 세 개념 간의 포함 관계를 올바르게 나타낸 것은 무엇인가? (단, A⊂B는 &quot;A는 B의 부분집합이다&quot;를 의미한다)</p>","choices":[{"n":1,"html":"딥러닝 ⊃ 인공지능 ⊃ 머신러닝"},{"n":2,"html":"인공지능 ⊃ 머신러닝 ⊃ 딥러닝"},{"n":3,"html":"딥러닝 ⊃ 머신러닝 ⊃ 인공지능"},{"n":4,"html":"인공지능 ⊃ 딥러닝 ⊃ 머신러닝"}],"answer":[2],"explain":{"mine":"<p>포함 관계는 <b>인공지능 ⊃ 머신러닝 ⊃ 딥러닝</b>입니다(2번). 머신러닝은 인공지능을 구현하는 방법의 하나이고, 딥러닝은 심층 신경망을 쓰는 머신러닝의 한 분야입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a80","number":11,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터의 유형과 그에 맞는 수집 방법을 짝지은 것 중 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"실시간 데이터 - 오픈 API"},{"n":2,"html":"웹 문서 데이터 - 크롤링"},{"n":3,"html":"웹 로그 데이터 - FTP"},{"n":4,"html":"웹 메타 데이터 - 스크래핑"}],"answer":[3],"explain":{"mine":"<p>FTP는 파일 송수신 프로토콜이라 <b>실시간으로 쌓이는 웹 로그 수집에는 부적절</b>합니다(3번이 답). 웹 로그에는 Flume·Scribe·Chukwa 같은 로그 수집기를 씁니다. 오픈 API(실시간), 크롤링(웹 문서), 스크래핑(웹 데이터 추출)의 짝은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a88","number":12,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 처리 과정인 수집 → 저장 → 처리 → 분석 → 시각화 단계 가운데, 데이터를 수집하고 저장하는 과정에서 활용하는 도구로 보기 어려운 것은?</p>","choices":[{"n":1,"html":"텍스트 마이닝(Text Mining)"},{"n":2,"html":"하둡(Hadoop)"},{"n":3,"html":"NoSQL"},{"n":4,"html":"GFS(Google File System)"}],"answer":[1],"explain":{"mine":"<p>하둡·NoSQL·GFS는 데이터의 <b>수집·저장</b>을 담당하는 인프라입니다. <b>텍스트 마이닝은 저장된 데이터를 분석하는 기법</b>이므로 수집·저장 도구로 보기 어렵습니다(1번).</p>"}},{"id":"6a6a00571bbde79cd2c72a77","number":13,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>기업 내부의 잠재적 데이터 소스를 평가한 뒤 통합하고 집중화하며, 데이터 보호 및 관리 계획을 수립하고, 데이터 관리 시스템의 성능을 상시 모니터링하여 보고하는 역할을 수행하는 직무는 무엇인가?</p>","choices":[{"n":1,"html":"데이터 아키텍트(Data Architect)"},{"n":2,"html":"데이터 엔지니어(Data Engineer)"},{"n":3,"html":"데이터 분석가(Data Analyst)"},{"n":4,"html":"데이터 사이언티스트(Data Scientist)"}],"answer":[1],"explain":{"mine":"<p>데이터 소스의 평가·통합·집중화, 데이터 보호·관리 계획 수립, 관리 시스템 성능 모니터링은 데이터의 전체 구조를 설계·관리하는 <b>데이터 아키텍트</b>의 역할입니다(1번).</p>"}},{"id":"6a6a00571bbde79cd2c72a7b","number":14,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 로드맵 수립이나 분석 기획 업무에 관한 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"향후 데이터 분석모형의 발전 계획도 기획 단계에서 수립해야 한다."},{"n":2,"html":"데이터 분석 프로젝트를 수행하는 데 필요한 비용(인건비, 하드웨어 및 소프트웨어 비용 등)을 고려해야 한다."},{"n":3,"html":"분석 로드맵을 설정할 때 Work Breakdown Structure를 활용하면 업무를 효율적으로 수행할 수 있다."},{"n":4,"html":"프로젝트 수행에 투입될 인원과 역할 정의 등 업무 분장 계획을 세우고 산출물을 정의해야 한다."}],"answer":[1],"explain":{"mine":"<p>분석모형의 <b>향후 발전 계획은 기획이 아니라 평가 및 전개 단계</b>에서 수립합니다. '기획 단계에서 수립해야 한다'는 1번이 옳지 않습니다. 비용 고려, WBS 활용, 인력·역할 정의는 기획 단계의 올바른 업무입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a82","number":15,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>측정 척도에 관한 다음 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"매출액이나 생산량과 같이 연속적인 값을 가질 수 있는 데이터는 계량적 변수인 연속형 변수로 표현하여 해석한다."},{"n":2,"html":"성별, 출신지, 직업, 국적 등과 같은 명목 척도 데이터는 비계량적 변수로 표현하여 해석한다."},{"n":3,"html":"범주형 척도 역시 연속형 척도와 마찬가지로 평균, 표준편차 등의 기술통계량을 산출하여 해석한다."},{"n":4,"html":"수치로 측정 가능한 데이터는 계량적 변수에 저장하며, 명목 및 서열 척도처럼 수치로 측정할 수 없는 데이터는 비계량적 변수에 저장한다."}],"answer":[3],"explain":{"mine":"<p>성별·직업 같은 범주형(명목) 척도는 <b>평균·표준편차를 계산할 수 없고</b> 빈도·최빈값으로 요약합니다. '범주형도 연속형처럼 평균·표준편차를 산출한다'는 3번이 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a7e","number":16,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>분석 프로젝트를 진행할 때마다 매번 기획 업무부터 새로 시작하는 것은 어렵고 비효율적이기 때문에, 데이터 거버넌스를 구축하고 체계화된 분석 절차와 방법을 활용하는 CRISP-DM이 요구된다. CRISP-DM 방법의 수행 절차로 옳은 것은?</p>","choices":[{"n":1,"html":"비즈니스 이해 → 데이터 준비 → 데이터 이해 → 평가 → 모델링 → 전개"},{"n":2,"html":"비즈니스 이해 → 데이터 이해 → 데이터 준비 → 평가 → 모델링 → 전개"},{"n":3,"html":"비즈니스 이해 → 데이터 준비 → 데이터 이해 → 모델링 → 평가 → 전개"},{"n":4,"html":"비즈니스 이해 → 데이터 이해 → 데이터 준비 → 모델링 → 평가 → 전개"}],"answer":[4],"explain":{"mine":"<p>CRISP-DM은 <b>비즈니스 이해 → 데이터 이해 → 데이터 준비 → 모델링 → 평가 → 전개</b> 순입니다(4번). 모델링 후에 평가가 온다는 순서를 기억하세요.</p>"}},{"id":"6a6a00571bbde79cd2c72a7d","number":17,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석 방안을 세우고 알맞은 분석모형을 구축하는 과정에서 활용되는 기법에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"인터뷰(Interview) : 상대방에게 특정 문제에 관해 질문하여 정보나 의견 등을 파악한다."},{"n":2,"html":"스캠퍼(Scamper) : 사고의 영역을 7개의 키워드(대체, 결합, 조정, 수정, 다른 용도 사용, 제거, 재정렬)로 설정하고, 이에 맞추어 새로운 아이디어를 만들어낸다."},{"n":3,"html":"브레인스토밍(Brainstorming) : 집단적이고 창의적인 발상 기법으로, 집단 구성원들이 자발적이고 자연스럽게 내놓은 아이디어 목록을 바탕으로 특정 문제의 해답을 찾으려 노력한다."},{"n":4,"html":"포커스그룹 인터뷰(Focus Group Interview) : 시계열 과거 값에 대한 시계열 모델 최적합을 찾기 위하여 소규모 그룹 예측값들의 회귀누적이동평균을 활용한다."}],"answer":[4],"explain":{"mine":"<p>포커스그룹 인터뷰(FGI)는 <b>소수의 참가자와 진행하는 그룹 토의</b>로 의견을 수렴하는 기법입니다. '시계열 모델의 회귀누적이동평균 활용' 운운한 4번은 FGI와 전혀 무관한 서술이라 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a81","number":18,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>행과 열로 이루어진 테이블 형태의 구조를 갖추지는 않았지만, 스키마와 메타 데이터의 특성을 지니고 있는 데이터 유형은?</p>","choices":[{"n":1,"html":"비정형 데이터"},{"n":2,"html":"정형 데이터"},{"n":3,"html":"비구조 데이터"},{"n":4,"html":"반정형 데이터"}],"answer":[4],"explain":{"mine":"<p>테이블 형태는 아니지만 <b>스키마·메타데이터를 스스로 지니고 있는</b> 데이터는 <b>반정형 데이터</b>입니다(4번). XML·JSON·HTML이 대표적입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a78","number":19,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래에서 설명하고 있는 것은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>같은 기종이나 서로 다른 기종의 데이터 소스에서 데이터를 추출한다.</li><li>조회나 분석에 활용할 수 있도록 알맞은 포맷 또는 구조로 저장하기 위해 데이터를 변환한다.</li><li>변환된 데이터를 최종 대상(데이터베이스, 데이터마트, 데이터웨어하우스 등)에 적재한다.</li></ul></div>","choices":[{"n":1,"html":"ETL"},{"n":2,"html":"DBMS"},{"n":3,"html":"Data Migration"},{"n":4,"html":"Open API"}],"answer":[1],"explain":{"mine":"<p>추출(Extract) → 변환(Transform) → 적재(Load)의 과정은 <b>ETL</b>입니다(1번). 여러 소스의 데이터를 DW·데이터마트로 옮기는 표준 파이프라인입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a7a","number":20,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음에서 설명하고 있는 기법으로 가장 알맞은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>이미 학습이 완료된 모델을 바탕으로 최종 출력층을 교체하여 학습을 진행함</li><li>보유하고 있는 데이터에 맞는 출력층으로 최종 출력층을 변경함</li><li>바꾼 출력층의 결합 파라미터를 적은 양의 데이터로 재학습함</li></ul></div>","choices":[{"n":1,"html":"비지도 학습(Unsupervised Learning)"},{"n":2,"html":"지도 학습(Supervised Learning)"},{"n":3,"html":"전이 학습(Transfer Learning)"},{"n":4,"html":"강화 학습(Reinforcement Learning)"}],"answer":[3],"explain":{"mine":"<p>학습이 끝난 모델의 <b>출력층만 교체하고 적은 데이터로 재학습(미세조정)</b>하는 기법은 <b>전이 학습(Transfer Learning)</b>입니다(3번). 사전 학습된 지식을 새 문제에 재활용하는 것이 핵심입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a8d","number":21,"category":"빅데이터 탐색","type":"choice","subject":"<p>회귀분석모형에서 과대적합을 막기 위한 기법으로 옳은 것은 다음 중 어느 것인가?</p>","choices":[{"n":1,"html":"이미 구축한 회귀분석모형을 활용해 학습 데이터를 랜덤하게 추가 생성하여 데이터 양을 늘린다."},{"n":2,"html":"(실젯값, 예측값)의 차이가 큰 학습 데이터를 회귀분석모형을 이용해 찾아 삭제한 뒤, 모형을 다시 구축한다."},{"n":3,"html":"벌점화 회귀방법을 활용해 회귀분석모형에 추가적인 제약조건을 부여한다."},{"n":4,"html":"데이터의 일부를 학습 과정에서 제외하고 회귀분석모형을 구축한다."}],"answer":[3],"explain":{"mine":"<p>회귀모형의 과대적합 방지책은 <b>벌점화(정규화) 회귀 — 릿지·라쏘처럼 계수에 제약을 추가</b>하는 것입니다(3번). 모형으로 데이터를 만들어 붓거나(1번) 오차 큰 데이터를 지우는 것(2번)은 잘못된 접근입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a90","number":22,"category":"빅데이터 탐색","type":"choice","subject":"<p>클래스별로 보유한 데이터 수의 격차가 심한 클래스 불균형 문제를 해결하기 위한 처리 기법으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"정규화(Normalization)"},{"n":2,"html":"언더 샘플링(Undersampling)"},{"n":3,"html":"오버 샘플링(Oversampling)"},{"n":4,"html":"반복 샘플링(Resampling)"}],"answer":[1],"explain":{"mine":"<p>클래스 불균형 해결책은 언더샘플링·오버샘플링·리샘플링입니다. <b>정규화는 값의 범위를 조정하는 스케일링 기법</b>이라 불균형과 무관하므로 1번이 답입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a99","number":23,"category":"빅데이터 탐색","type":"choice","subject":"<p>정규분포를 따르는 확률분포로부터 표본의 수=4인 확률변수를 뽑아 이를 각각 X₁, X₂, X₃, X₄라고 할 때, 다음 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"확률변수 X₂, X₃은 서로 종속 관계에 있다."},{"n":2,"html":"확률변수 X₁, X₂, X₃, X₄의 평균은 모집단의 평균(정규분포의 평균)과 같다."},{"n":3,"html":"확률변수 X₁, X₂, X₃, X₄로 추출된 표본의 값에 따라 표본평균은 매번 달라진다."},{"n":4,"html":"확률변수 X₁, X₂, X₃, X₄의 평균에 대한 분산(표본평균의 분산)은 모분산보다 작다."}],"answer":[1],"explain":{"mine":"<p>무작위로 추출한 표본 X₁~X₄는 <b>서로 독립</b>입니다. 'X₂, X₃이 종속 관계'라는 1번이 옳지 않습니다. 표본평균의 기댓값 = 모평균, 표본마다 표본평균이 달라짐, 표본평균의 분산(σ²/4) &lt; 모분산은 모두 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a9d","number":24,"category":"빅데이터 탐색","type":"choice","subject":"<p>어떤 데이터세트가 정규분포를 따르는지 확인하고자 할 때, 정규성 검정 방법에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"콜모고로프-스미르노프 검정(Kolmogorov-smirnov Test)"},{"n":2,"html":"큐-큐 플롯(Quantile-quantile Plot)"},{"n":3,"html":"카이스퀘어 테스트(Chi-square Test)"},{"n":4,"html":"샤피로윌크 테스트(Shapiro-wilk Test)"}],"answer":[3],"explain":{"mine":"<p>정규성 검정에는 K-S 검정, 샤피로-윌크 검정, Q-Q 플롯(시각적 확인)이 쓰입니다. <b>카이제곱 검정은 주로 범주형 자료의 적합도·독립성 검정</b>에 사용되므로 보기 중 정규성 검정 방법으로 가장 거리가 멉니다(3번).</p>"}},{"id":"6a6a00571bbde79cd2c72a93","number":25,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래 표는 변수 A, B, C 간의 피어슨 상관계수를 나타낸 것이다. 다른 변수들과의 연관성이 가장 낮은 변수를 제거하려고 할 때 옳은 조치는?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>구 분</th><th>A</th><th>B</th><th>C</th></tr><tr><td>A</td><td>1</td><td>0.01</td><td>0.01</td></tr><tr><td>B</td><td>0.01</td><td>1</td><td>0.95</td></tr><tr><td>C</td><td>0.01</td><td>0.95</td><td>1</td></tr></table></div>","choices":[{"n":1,"html":"변수 C를 삭제한다."},{"n":2,"html":"변수 A를 삭제한다."},{"n":3,"html":"변수 B를 삭제한다."},{"n":4,"html":"변수 B와 C를 한꺼번에 삭제한다."}],"answer":[2],"explain":{"mine":"<p>A는 B·C와의 상관계수가 모두 0.01로 <b>다른 변수들과의 연관성이 가장 낮으므로</b> A를 삭제하는 것이 맞습니다(2번). B와 C는 0.95로 강하게 연관되어 있어 이 둘 중 하나를 정리하는 것은 다중공선성 관점의 별개 문제입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a8e","number":26,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석(Principal Component Analysis)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"변수들의 공분산 행렬과 상관행렬을 활용하여 주성분을 찾아낸다."},{"n":2,"html":"차원이 높은 데이터를 차원이 낮은 데이터로 변환한다."},{"n":3,"html":"원 데이터세트의 변수들에 선형 변환 또는 직교변환을 적용하여 저차원 공간의 주성분을 찾는다."},{"n":4,"html":"주성분을 설명하는 데 필요한 변수는 수집된 표본의 수보다 반드시 커야 한다."}],"answer":[4],"explain":{"mine":"<p>PCA에 변수 수가 표본 수보다 <b>커야 한다는 제약은 없습니다</b>(4번이 옳지 않음). 오히려 표본이 변수보다 많은 것이 일반적입니다. 공분산·상관행렬 활용, 고차원→저차원 변환, 선형(직교) 변환 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a8f","number":27,"category":"빅데이터 탐색","type":"choice","subject":"<p>범주형 변수를 숫자형 변수로 바꾸는 데 활용되는 기법에 관한 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"원-핫 인코딩(One-hot Encoding) : 표현하려는 단어 집합 변수의 인덱스에는 1의 값을 부여하고 나머지 인덱스에는 0을 부여한다."},{"n":2,"html":"타깃 인코딩(Target Encoding) : 분석 대상이 되는 범주형 변수에 대한 표준편차를 실수 벡터로 변환한 뒤, 임베딩 계층에서 범주형 변수를 부여해 학습한다."},{"n":3,"html":"레이블 인코딩(Label Encoding) : 범주형 변수의 레벨 각각을 단순하게 정수로 바꾼다."},{"n":4,"html":"특징 해싱(Feature Hashing) : 데이터 변환 후 특징의 개수를 미리 정해 두고, 해시 함수를 활용해 레벨별로 플래그를 표시할 위치를 정한다."}],"answer":[2],"explain":{"mine":"<p>타깃 인코딩은 <b>범주별 목표변수(타깃)의 평균값 등으로 범주를 대체</b>하는 기법입니다. '표준편차를 실수 벡터로 변환해 임베딩 계층에서 학습한다'는 2번은 타깃 인코딩의 설명이 아닙니다(임베딩에 대한 설명이 뒤섞임).</p>"}},{"id":"6a6a00571bbde79cd2c72a92","number":28,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 분석모형을 구축할 때 고려할 사항으로 옳은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"가중치 업데이트 - 배치 사이즈를 결정할 때 소수 클래스는 무시한다."},{"n":2,"html":"비용 민감 학습 - 다수 클래스 데이터에 더 민감하게 학습되도록 더 작은 클래스 가중치(비용 함수)를 부여한다."},{"n":3,"html":"데이터 샘플링 - 데이터의 불균형을 해소하여 학습하기 위해 오버 샘플링과 언더 샘플링 기법을 활용한다."},{"n":4,"html":"소수 클래스 추가 수집 - 심하게 상호 균형적인 데이터가 불균형 데이터가 되게끔 소수 클래스를 추가로 수집한다."}],"answer":[3],"explain":{"mine":"<p>불균형 데이터 학습에는 <b>오버샘플링·언더샘플링으로 균형을 맞추는 데이터 샘플링</b>이 올바른 접근입니다(3번). 비용 민감 학습은 소수 클래스에 더 큰 가중치를 주는 것이므로 2번은 반대이고, 1·4번도 잘못된 서술입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a8c","number":29,"category":"빅데이터 탐색","type":"choice","subject":"<p>상자수염 그림(Box and Whisker 또는 Box-plot) 및 이상값에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"수염은 사분위범위(IQR, Interquartile Range)의 1.5배~3배만큼 멀리 떨어져 있는 데이터까지 연결된다."},{"n":2,"html":"상자수염 그림에서는 최솟값, 제1사분위, 제2사분위, 제3사분위, 최댓값과 더불어 이상값도 함께 표현된다."},{"n":3,"html":"제1사분위수와 제3사분위수 바깥의 변동성은 수염(선)으로 나타내며, 선 또는 수염 밖에 위치한 모든 점은 이상값으로 간주된다."},{"n":4,"html":"상자수염 그림은 사분위수를 이용해 데이터 분포를 나타내며, 중위값과 이상값을 강조해 보여준다."}],"answer":[1],"explain":{"mine":"<p>수염은 통상 Q1−1.5×IQR ~ Q3+1.5×IQR <b>범위 안에 있는 실제 최솟값·최댓값까지만</b> 연결됩니다. '1.5배~3배만큼 떨어져 있는 데이터까지 연결된다'는 1번이 옳지 않습니다. 수염 밖의 점을 이상값으로 표시한다는 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a98","number":30,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률분포에 관한 다음 설명 가운데 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"초기하분포, 지수분포, 정규분포는 연속확률분포에 해당한다."},{"n":2,"html":"베르누이 분포, 포아송분포, 다항분포는 이산확률분포에 해당한다."},{"n":3,"html":"확률분포는 데이터가 이산형인지 연속형인지에 따라 구분되며, 그 특징을 사전에 파악하여 활용한다."},{"n":4,"html":"확률분포란 확률변수를 중심으로 하여 확률변수의 특성에 따라 확률로 나타낸 분포를 말한다."}],"answer":[1],"explain":{"mine":"<p><b>초기하분포는 비복원추출의 성공 횟수를 세는 이산확률분포</b>입니다. 이를 연속확률분포로 분류한 1번이 옳지 않습니다. 베르누이·포아송·다항분포가 이산이라는 2번은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a96","number":31,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음은 K 대학 병원에서 초기 암환자와 말기 암환자에게 신약(A, B)을 투여한 뒤 그 효과를 측정한 데이터이다. 이에 대한 분석으로 옳지 않은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>구 분</th><th>암 초기 - 생존자 수</th><th>암 초기 - 사망자 수</th><th>암 말기 - 생존자 수</th><th>암 말기 - 사망자 수</th><th>합계 - 생존자 수</th><th>합계 - 사망자 수</th></tr><tr><td>신약 A</td><td>18</td><td>2</td><td>2</td><td>8</td><td>20</td><td>10</td></tr><tr><td>신약 B</td><td>7</td><td>3</td><td>9</td><td>21</td><td>16</td><td>24</td></tr></table></div>","choices":[{"n":1,"html":"신약 A를 투여받은 환자의 생존율은 50%이며, 신약 B를 투여받은 환자의 생존율은 40%이다."},{"n":2,"html":"암 말기 환자들만 놓고 보면 신약 A의 생존율이 신약 B의 생존율보다 낮다."},{"n":3,"html":"암 초기 환자들만 놓고 보면 신약 A의 생존율이 신약 B의 생존율보다 높다."},{"n":4,"html":"K대학 병원에서의 암 환자 생존율은 50% 이상이다."}],"answer":[1],"explain":{"mine":"<p>신약 A의 생존율은 20/30 ≈ <b>66.7%</b>(50%가 아님)이므로 1번이 옳지 않습니다. 말기만 보면 A 20% &lt; B 30%(2번 맞음), 초기만 보면 A 90% &gt; B 70%(3번 맞음), 전체 생존율 36/70 ≈ 51.4%(4번 맞음). 부분과 전체의 결론이 뒤집히는 심슨의 역설 사례로도 유명한 구조입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a91","number":32,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 그림에서 보듯이 데이터 분석모형을 효율적으로 학습시키기 위해 활용되는 Undersampling(데이터 수를 줄임) 또는 Oversampling(데이터 수를 늘림)에 해당하는 개념은 무엇인가?</p><div class=\"q-fig\">\n  <svg class=\"q-fig__svg\" viewBox=\"0 0 740 260\" width=\"740\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"언더샘플링, 원본, 오버샘플링의 다수 및 소수 클래스 데이터 크기 비교 개념도\">\n    <!-- Y-axis -->\n    <path d=\"M 50 210 L 50 40\" stroke=\"currentColor\" stroke-width=\"2\" fill=\"none\" />\n    <polyline points=\"45,47 50,37 55,47\" stroke=\"currentColor\" stroke-width=\"2\" fill=\"none\" />\n    <text x=\"50\" y=\"25\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">Count</text>\n\n    <!-- Reference lines -->\n    <line x1=\"50\" y1=\"60\" x2=\"690\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"2,4\" />\n    <line x1=\"50\" y1=\"150\" x2=\"690\" y2=\"150\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"2,4\" />\n\n    <!-- Baselines -->\n    <line x1=\"70\" y1=\"210\" x2=\"250\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"2\" />\n    <line x1=\"290\" y1=\"210\" x2=\"470\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"2\" />\n    <line x1=\"510\" y1=\"210\" x2=\"690\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"2\" />\n\n    <!-- Legend -->\n    <rect x=\"100\" y=\"20\" width=\"16\" height=\"16\" fill=\"rgb(180,180,180)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <text x=\"125\" y=\"33\" font-size=\"14\" fill=\"currentColor\">Majority Class</text>\n    <rect x=\"100\" y=\"45\" width=\"16\" height=\"16\" fill=\"rgb(60,60,60)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <text x=\"125\" y=\"58\" font-size=\"14\" fill=\"currentColor\">Minority Class</text>\n\n    <!-- Group 1: Undersampling -->\n    <rect x=\"95\" y=\"150\" width=\"50\" height=\"60\" fill=\"rgb(180,180,180)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <rect x=\"175\" y=\"150\" width=\"50\" height=\"60\" fill=\"rgb(60,60,60)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <text x=\"160\" y=\"240\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"bold\">Undersampling</text>\n\n    <!-- Group 2: Original -->\n    <rect x=\"315\" y=\"60\" width=\"50\" height=\"150\" fill=\"rgb(180,180,180)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <rect x=\"395\" y=\"150\" width=\"50\" height=\"60\" fill=\"rgb(60,60,60)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <text x=\"380\" y=\"240\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"bold\">Original</text>\n\n    <!-- Group 3: Oversampling -->\n    <rect x=\"535\" y=\"60\" width=\"50\" height=\"150\" fill=\"rgb(180,180,180)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <rect x=\"615\" y=\"60\" width=\"50\" height=\"150\" fill=\"rgb(60,60,60)\" stroke=\"currentColor\" stroke-width=\"1\" />\n    <text x=\"600\" y=\"240\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"bold\">Oversampling</text>\n  </svg>\n</div>","choices":[{"n":1,"html":"클래스 학습 데이터 삭제"},{"n":2,"html":"클래스 변수 축소"},{"n":3,"html":"클래스 변수 변환"},{"n":4,"html":"클래스 불균형 해소"}],"answer":[4],"explain":{"mine":"<p>다수 클래스를 줄이는 언더샘플링과 소수 클래스를 늘리는 오버샘플링은 모두 <b>클래스 불균형 해소</b>를 위한 기법입니다(4번).</p>"}},{"id":"6a6a00571bbde79cd2c72a9f","number":33,"category":"빅데이터 탐색","type":"choice","subject":"<p>K 바이오기업이 체중 감량을 목적으로 하는 신약을 개발했다. 무작위로 선정한 20명에게 이 신약을 복용시킨 다음, 복용 전과 후의 효과를 비교하고자 한다. 복용 이후 체중이 줄었는지 검정하려 할 때 적절한 표본추출 및 검정방법은 무엇인가?</p>","choices":[{"n":1,"html":"독립표본, 단측검정"},{"n":2,"html":"대응표본, 양측검정"},{"n":3,"html":"대응표본, 단측검정"},{"n":4,"html":"독립표본, 양측검정"}],"answer":[3],"explain":{"mine":"<p>같은 사람의 복용 전·후를 비교하므로 <b>대응표본</b>이고, '체중이 줄었는지'라는 한 방향의 가설을 검정하므로 <b>단측검정</b>입니다(3번).</p>"}},{"id":"6a6a00571bbde79cd2c72a94","number":34,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 그림처럼 X축과 Y축으로 이루어진 평면 위에 데이터를 시각화한 표현 방식을 무엇이라 부르는가?</p><div class=\"q-fig\">\n  <svg class=\"q-fig__svg\" viewBox=\"0 0 600 350\" width=\"600\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"X·Y 평면 위에 개별 데이터 점들이 흩어져 있는 그래프\">\n    <line x1=\"60\" y1=\"290\" x2=\"560\" y2=\"290\" stroke=\"currentColor\" stroke-width=\"2\"/>\n    <line x1=\"60\" y1=\"290\" x2=\"60\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"2\"/>\n    <polygon points=\"560,290 545,283 545,297\" fill=\"currentColor\"/>\n    <polygon points=\"60,40 53,55 67,55\" fill=\"currentColor\"/>\n    <text x=\"550\" y=\"330\" font-size=\"20\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\" font-family=\"sans-serif\">X</text>\n    <text x=\"30\" y=\"55\" font-size=\"20\" fill=\"currentColor\" text-anchor=\"end\" font-style=\"italic\" font-family=\"sans-serif\">Y</text>\n    <line x1=\"60\" y1=\"240\" x2=\"540\" y2=\"240\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"60\" y1=\"190\" x2=\"540\" y2=\"190\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"60\" y1=\"140\" x2=\"540\" y2=\"140\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"60\" y1=\"90\" x2=\"540\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"160\" y1=\"290\" x2=\"160\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"260\" y1=\"290\" x2=\"260\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"360\" y1=\"290\" x2=\"360\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <line x1=\"460\" y1=\"290\" x2=\"460\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"0.5\" stroke-dasharray=\"4,4\"/>\n    <g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n      <circle cx=\"100\" cy=\"80\" r=\"6\"/>\n      <circle cx=\"120\" cy=\"110\" r=\"6\"/>\n      <circle cx=\"140\" cy=\"90\" r=\"6\"/>\n      <circle cx=\"150\" cy=\"70\" r=\"6\"/>\n      <circle cx=\"180\" cy=\"130\" r=\"6\"/>\n      <circle cx=\"200\" cy=\"100\" r=\"6\"/>\n      <circle cx=\"230\" cy=\"160\" r=\"6\"/>\n      <circle cx=\"250\" cy=\"120\" r=\"6\"/>\n      <circle cx=\"260\" cy=\"140\" r=\"6\"/>\n      <circle cx=\"280\" cy=\"180\" r=\"6\"/>\n      <circle cx=\"310\" cy=\"150\" r=\"6\"/>\n      <circle cx=\"340\" cy=\"210\" r=\"6\"/>\n      <circle cx=\"360\" cy=\"170\" r=\"6\"/>\n      <circle cx=\"370\" cy=\"190\" r=\"6\"/>\n      <circle cx=\"390\" cy=\"230\" r=\"6\"/>\n      <circle cx=\"420\" cy=\"200\" r=\"6\"/>\n      <circle cx=\"450\" cy=\"250\" r=\"6\"/>\n      <circle cx=\"460\" cy=\"210\" r=\"6\"/>\n      <circle cx=\"480\" cy=\"220\" r=\"6\"/>\n      <circle cx=\"500\" cy=\"260\" r=\"6\"/>\n      <circle cx=\"520\" cy=\"240\" r=\"6\"/>\n    </g>\n  </svg>\n</div>","choices":[{"n":1,"html":"파이 차트(Pie Chart)"},{"n":2,"html":"히스토그램(Histogram)"},{"n":3,"html":"산점도(Scatter Diagram)"},{"n":4,"html":"상자수염 그림(Box and Whisker Plot)"}],"answer":[3],"explain":{"mine":"<p>X-Y 평면 위에 관측값들을 점으로 뿌려 두 변수의 관계를 보여주는 그래프는 <b>산점도</b>입니다(3번).</p>"}},{"id":"6a6a00571bbde79cd2c72a95","number":35,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음은 지역별 소득금액의 분포를 나타낸 것이다. 설문 조사 중 일부 응답자의 값이 결측되어 이를 다른 값으로 대체하려고 할 때, 가장 적절한 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 700 300\" width=\"700\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"지역별 소득 차이를 나타내는 높이와 폭이 다른 두 봉우리의 분포 곡선\"><path d=\"M88 246V27 M82 38L88 27L94 38\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M88 246H679 M668 240L679 246L668 252\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"46\" y=\"55\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">소 득</text><text x=\"628\" y=\"279\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">지 역</text><path d=\"M103 231 C132 229 151 212 170 169 C191 120 211 78 243 87 C279 97 293 166 326 194 C350 213 377 214 405 200 C434 185 448 131 468 81 C485 39 512 38 530 76 C553 127 555 190 589 216 C612 232 638 234 661 231\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>","choices":[{"n":1,"html":"최빈수(Mode)"},{"n":2,"html":"중앙값(Median)"},{"n":3,"html":"범위(Range)"},{"n":4,"html":"평균(Mean)"}],"answer":[2],"explain":{"mine":"<p>소득 자료는 일부 고소득자 때문에 오른쪽으로 치우친 비대칭 분포가 전형적이므로, 극단값에 강건한 <b>중앙값</b>으로 대체하는 것이 가장 적절합니다(2번). 평균은 극단값에 끌려가 대표성이 떨어집니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a9c","number":36,"category":"빅데이터 탐색","type":"choice","subject":"<p>모집단의 표준편차가 알려져 있지 않을 때, 집단 간 평균 차이를 검정하는 데 사용하는 분포로 가장 적절한 것은? (단, 표본의 수는 n이다)</p>","choices":[{"n":1,"html":"카이제곱 분포, 자유도=n-1"},{"n":2,"html":"t분포, 자유도=n-1"},{"n":3,"html":"카이제곱 분포, 자유도=n"},{"n":4,"html":"t분포, 자유도=n"}],"answer":[2],"explain":{"mine":"<p>모표준편차를 모를 때 평균(차이) 검정에는 <b>자유도 n−1의 t분포</b>를 사용합니다(2번). 카이제곱 분포는 분산에 대한 추론에 쓰입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a9a","number":37,"category":"빅데이터 탐색","type":"choice","subject":"<p>중심극한정리(Central Limit Theorem)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"표본의 크기가 클 때 표본평균의 분산은 모분산보다 작다."},{"n":2,"html":"같은 확률분포를 따르는 n개의 독립확률변수에 대해, n이 충분히 크면 그 평균의 분포는 정규분포에 근접한다."},{"n":3,"html":"표본평균의 기댓값은 표본의 크기와 관계없이 항상 모평균과 같다."},{"n":4,"html":"표본평균의 분포가 정규분포에 가까워지려면 모집단이 반드시 정규분포를 따라야 한다."}],"answer":[4],"explain":{"mine":"<p>중심극한정리의 핵심은 <b>모집단의 분포와 무관하게</b> n이 크면 표본평균이 정규분포에 근사한다는 것입니다. '모집단이 반드시 정규분포를 따라야 한다'는 4번이 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a8b","number":38,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 탐색에 관한 다음 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"박스플롯의 제1사분위수는 전체 데이터에서 하위 75%에 해당하는 값을 의미한다."},{"n":2,"html":"박스플롯의 제2사분위수는 중앙값(Median)과 같은 값이다."},{"n":3,"html":"박스플롯의 제3사분위수는 전체 데이터에서 상위 25%에 해당하는 값을 의미한다."},{"n":4,"html":"패턴을 파악하기 위해 데이터를 탐색·시각화하는 도구로 박스플롯을 활용할 수 있다."}],"answer":[1],"explain":{"mine":"<p>제1사분위수(Q1)는 <b>하위 25%</b> 지점의 값입니다. '하위 75%'라고 한 1번이 옳지 않습니다. Q2 = 중앙값, Q3 = 상위 25%(하위 75%) 지점이라는 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72a9e","number":39,"category":"빅데이터 탐색","type":"choice","subject":"<p>어느 데이터 분석 경진대회 참가자 가운데 121명을 대상으로 연령을 조사한 결과 평균 연령이 35세로 나타났다. 평균에 대한 95% 신뢰구간을 구하면? (단, 연령의 모표준편차는 11세로 알려져 있으며, 표준정규분포(Z)에서 P(Z&gt;1.96)=0.025, P(Z&gt;1.64)=0.05이다)</p>","choices":[{"n":1,"html":"(33.04, 36.96)"},{"n":2,"html":"(33.04, 36.64)"},{"n":3,"html":"(33.36, 36.64)"},{"n":4,"html":"(33.36, 36.96)"}],"answer":[1],"explain":{"mine":"<p>모표준편차를 알고 있으므로 Z-분포를 사용합니다. 신뢰구간 = 35 ± 1.96 × 11/√121 = 35 ± 1.96 × 1 = <b>(33.04, 36.96)</b>입니다(1번).</p>"}},{"id":"6a6a00571bbde79cd2c72a97","number":40,"category":"빅데이터 탐색","type":"choice","subject":"<p>일정한 시간이나 공간 내에서 특정 사건이 몇 번 발생하는지를 확률변수로 하는 확률분포로 옳은 것은?</p>","choices":[{"n":1,"html":"초기하분포(Hypergeometric Distribution)"},{"n":2,"html":"이항분포(Binomial Distribution)"},{"n":3,"html":"균일분포(Uniform Distribution)"},{"n":4,"html":"포아송분포(Poisson Distribution)"}],"answer":[4],"explain":{"mine":"<p>단위 시간·공간에서 사건의 <b>발생 횟수</b>를 확률변수로 하는 분포는 <b>포아송분포</b>입니다(4번). 콜센터 전화 수, 창구 방문 고객 수가 대표적 예입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72ab0","number":41,"category":"빅데이터 모델링","type":"choice","subject":"<p>텍스트 마이닝 분야에서 단어를 벡터(또는 행렬) 형태로 변환하는 기법(Text to Vector)에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"Word2Vec"},{"n":2,"html":"POS Tagging"},{"n":3,"html":"Term Frequency-Inverse Document Frequency(TF-IDF)"},{"n":4,"html":"Doc2Vec"}],"answer":[2],"explain":{"mine":"<p>Word2Vec, TF-IDF, Doc2Vec은 텍스트를 벡터로 바꾸는 기법입니다. <b>POS Tagging은 단어에 품사를 부착하는 전처리</b>이지 벡터화 기법이 아니므로 2번이 답입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab3","number":42,"category":"빅데이터 모델링","type":"choice","subject":"<p>중위수(Median)와 순위합(Rank Sum)을 활용하는 검정 방법에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"런검정(Run Test)은 표본의 독립성을 검정하기 위해 사용하는 비모수 검정 방법으로, 중위수보다 큰 값(혹은 작은 값)을 측정한다."},{"n":2,"html":"맨-휘트니(Mann-Whitney) 검정은 두 모집단의 확률분포가 동일한지에 대한 가설을 검정하고자 순위합을 이용하는 양측 모수 검정방법이다."},{"n":3,"html":"프리드만 검정(Friedman Test)은 동일한 케이스에 반복 측정이 이루어진 경우 세 개 이상의 집단을 비교하기 위한 비모수 검정 방법으로, 순위의 합을 이용한다."},{"n":4,"html":"부호검정(Sign Test)은 두 표본의 분포가 동일한지를 판단하는 비모수적 검정 방법으로, 중앙값을 이용해 비교한다."}],"answer":[2],"explain":{"mine":"<p>맨-휘트니 검정은 순위합을 이용하는 <b>비모수</b> 검정인데 '모수 검정방법'이라고 한 2번이 옳지 않습니다. 런검정(독립성·무작위성), 프리드만 검정(반복측정 3집단 이상), 부호검정(중앙값 기반)의 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa4","number":43,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 그래프를 바탕으로 상관계수를 계산하면 얼마인가? (단, 두 변수 X와 Y의 공분산=-0.9, X의 분산=4, Y의 분산=0.25로 주어진다)</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 480 300\" width=\"480\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"우하향 경향을 보이는 X와 Y의 산점도\"><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"55\" y1=\"255\" x2=\"455\" y2=\"255\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#ah)\"/><line x1=\"55\" y1=\"255\" x2=\"55\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#ah)\"/><line x1=\"120\" y1=\"255\" x2=\"120\" y2=\"262\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"190\" y1=\"255\" x2=\"190\" y2=\"262\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"260\" y1=\"255\" x2=\"260\" y2=\"262\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"330\" y1=\"255\" x2=\"330\" y2=\"262\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"400\" y1=\"255\" x2=\"400\" y2=\"262\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"48\" y1=\"210\" x2=\"55\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"48\" y1=\"165\" x2=\"55\" y2=\"165\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"48\" y1=\"120\" x2=\"55\" y2=\"120\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"48\" y1=\"75\" x2=\"55\" y2=\"75\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"462\" y=\"278\" font-size=\"15\" fill=\"currentColor\">X</text><text x=\"30\" y=\"28\" font-size=\"15\" fill=\"currentColor\">Y</text><circle cx=\"85\" cy=\"70\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"110\" cy=\"96\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"135\" cy=\"62\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"152\" cy=\"108\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"178\" cy=\"88\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"205\" cy=\"128\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"228\" cy=\"104\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"252\" cy=\"148\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"278\" cy=\"126\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"302\" cy=\"168\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"326\" cy=\"146\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"350\" cy=\"192\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"374\" cy=\"170\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"398\" cy=\"214\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"424\" cy=\"196\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"440\" cy=\"228\" r=\"4.5\" fill=\"currentColor\"/></svg></div>","choices":[{"n":1,"html":"0.1"},{"n":2,"html":"-0.9"},{"n":3,"html":"-0.1"},{"n":4,"html":"0.9"}],"answer":[2],"explain":{"mine":"<p>상관계수 = 공분산 ÷ (X 표준편차 × Y 표준편차) = −0.9 ÷ (2 × 0.5) = <b>−0.9</b>입니다(2번).</p>"}},{"id":"6a6a00571bbde79cd2c72aab","number":44,"category":"빅데이터 모델링","type":"choice","subject":"<p>군집분석을 실시하여 아래와 같은 덴드로그램을 얻었다. 군집 간 거리(Height)의 절단 기준을 Y=4로 설정할 경우 형성되는 군집의 개수는?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 700 320\" width=\"700\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"서로 다른 병합 구조로 배치한 다섯 개 개체의 덴드로그램과 Y=4 절단선\"><defs><marker id=\"height-arrow-new\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10Z\" fill=\"currentColor\"/></marker></defs><line x1=\"76\" y1=\"276\" x2=\"76\" y2=\"24\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#height-arrow-new)\"/><text x=\"91\" y=\"34\" font-size=\"16\" fill=\"currentColor\">Height</text><line x1=\"86\" y1=\"122\" x2=\"688\" y2=\"122\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-dasharray=\"10 7\"/><text x=\"67\" y=\"127\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\" font-style=\"italic\">Y=4</text><path d=\"M140 272V174H302.5M250 272V224H355V272M302.5 224V174M221.25 174V66H585M515 272V198H655V272M585 198V66\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linejoin=\"round\"/><text x=\"140\" y=\"301\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">1</text><text x=\"250\" y=\"301\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">2</text><text x=\"355\" y=\"301\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">3</text><text x=\"515\" y=\"301\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">4</text><text x=\"655\" y=\"301\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">5</text></svg></div>","choices":[{"n":1,"html":"1"},{"n":2,"html":"2"},{"n":3,"html":"3"},{"n":4,"html":"4"}],"answer":[2],"explain":{"mine":"<p>덴드로그램에서 절단선 Y=4가 가로지르는 세로선의 개수가 군집 수입니다. 이 그림에서는 Y=4 아래에서 이미 병합이 진행되어 절단선이 두 개의 세로선을 지나므로 <b>2개</b>의 군집이 형성됩니다(2번).</p>"}},{"id":"6a6a00571bbde79cd2c72aad","number":45,"category":"빅데이터 모델링","type":"choice","subject":"<p>매일 측정된 미세먼지 농도가 시간의 흐름에 따라 어떻게 변하는지 분석하려고 한다. 이때 활용하기에 가장 적절한 데이터 분석모형은?</p>","choices":[{"n":1,"html":"시계열 분석(Time Series Analysis)"},{"n":2,"html":"다변량 분석(Multivariate Analysis)"},{"n":3,"html":"앙상블 분석(Ensemble Analysis)"},{"n":4,"html":"군집분석(Clustering Analysis)"}],"answer":[1],"explain":{"mine":"<p>시간의 흐름에 따른 미세먼지 농도의 변화·추세·계절성을 분석하는 데는 <b>시계열 분석</b>이 적합합니다(1번).</p>"}},{"id":"6a6a00571bbde79cd2c72ab2","number":46,"category":"빅데이터 모델링","type":"choice","subject":"<p>앙상블 분석모형을 최적화하는 방법에 관한 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"훈련 데이터세트를 무작위로 다른 데이터세트로 만들어 결정트리 분류기를 구성하고, 여러 모형 가운데 가장 많은 선택을 받은 클래스를 예측한다."},{"n":2,"html":"여러 가지 모형을 독립적으로 이용해 구축한 앙상블 분석모형을 평가하기 위한 데이터세트를 다양화한다."},{"n":3,"html":"여러 개의 데이터 분석모형이 조화를 이루도록 학습시킨다."},{"n":4,"html":"훈련 데이터세트의 중복을 허용해 샘플링하거나, 약한 학습기 여러 개를 서로 연결·보완해 가며 더 강한 학습기를 만든다."}],"answer":[2],"explain":{"mine":"<p>앙상블 최적화는 학습 데이터의 다양화(배깅)나 약한 학습기의 결합(부스팅)으로 이루어집니다. '<b>평가 데이터세트를 다양화</b>한다'는 2번은 앙상블 최적화와 무관한 서술이라 옳지 않습니다 — 평가 데이터는 고정된 기준이어야 합니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa1","number":47,"category":"빅데이터 모델링","type":"choice","subject":"<p>두 확률변수 간의 상관관계를 분석할 때 활용하는 공분산(Covariance)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"두 확률변수 X, Y 사이의 공분산을 통해 상관관계의 경향을 파악할 수 있다."},{"n":2,"html":"두 확률변수 중 한 값이 상승하는 경향일 때 다른 값도 함께 상승하는 선형 상관성이 존재하면 공분산은 양수의 값을 가진다."},{"n":3,"html":"두 확률변수 X, Y의 공분산이 0이라면, 두 확률변수 X, Y는 항상 독립이다."},{"n":4,"html":"두 확률변수 중 한 값이 상승하는 경향일 때 다른 값은 하강하는 선형 상관성이 존재하면 공분산은 음수의 값을 가진다."}],"answer":[3],"explain":{"mine":"<p>공분산이 0이라고 해서 <b>항상 독립인 것은 아닙니다</b>(3번이 옳지 않음). 공분산은 선형 관계만 포착하므로 비선형 종속 관계(예: Y=X²)에서도 0이 될 수 있습니다. 독립이면 공분산이 0인 것은 맞지만 그 역은 성립하지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aac","number":48,"category":"빅데이터 모델링","type":"choice","subject":"<p>인자분석(Factor Analysis)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"인자분석에 사용되는 공분산 행렬은 행의 수와 열의 수가 서로 같아야 한다."},{"n":2,"html":"회귀분석, 상관분석, 판별분석 등에 활용할 소수의 변수를 새로 생성하기 위한 목적으로 사용된다."},{"n":3,"html":"분석 대상이 되는 변수들이 서로 연관성을 지니면서 소수의 요인으로 분석될 수 있는 경우에 활용되며, 그 요인들을 찾아내 변수의 수를 줄이는 차원축소 방법으로 쓰인다."},{"n":4,"html":"서로 연관된 여러 변수들 사이의 내부적 상호 관계로부터, 변수들에 내재하는 소수의 잠재적이며 관측 불가능한 인자를 추출하는 다변량 분석방법의 하나이다."}],"answer":[1],"explain":{"mine":"<p>인자분석의 <b>입력 데이터는 관측치×변수 형태라 행과 열의 수가 같을 필요가 없습니다</b>. '행의 수와 열의 수가 서로 같아야 한다'는 제약을 단 1번이 옳지 않습니다(공분산·상관행렬은 계산 과정에서 자연히 정방행렬이 될 뿐입니다). 잠재 인자 추출, 차원축소 목적 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa2","number":49,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석모형에 관한 설명 중 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"종속변수에 유의한 독립변수가 2개 이상인 경우를 단순(Simple)회귀분석이라고 부른다."},{"n":2,"html":"독립변수가 2개 이상이면서 차수가 2차 이상이라면 다항회귀분석모형에 해당한다."},{"n":3,"html":"분석하려는 종속변수가 2개 이상인 경우를 Univariate(단변량) 회귀분석이라고 부른다."},{"n":4,"html":"회귀분석모형에서 회귀계수(Regression Coefficient)는 독립변수와 종속변수 간에 아무런 영향을 주지 않는다."}],"answer":[2],"explain":{"mine":"<p><b>독립변수가 2개 이상이고 차수가 2차 이상이면 다항회귀분석</b>이 맞습니다(2번). 단순회귀는 독립변수 1개(1번 오답), 종속변수가 2개 이상이면 다변량(Multivariate) 회귀(3번 오답), 회귀계수는 독립변수가 종속변수에 미치는 영향의 크기를 나타냅니다(4번 오답).</p>"}},{"id":"6a6a00571bbde79cd2c72aa9","number":50,"category":"빅데이터 모델링","type":"choice","subject":"<p>인공신경망 분석모형의 과적합(Overfitting)을 줄이는 데 활용하는 기법으로 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"은닉층 노드 삭제"},{"n":2,"html":"데이터 학습률 수정"},{"n":3,"html":"가지치기(Tree Pruning)"},{"n":4,"html":"드롭 아웃(Dropout)"}],"answer":[3],"explain":{"mine":"<p>은닉층 노드 축소, 학습률 조정, 드롭아웃은 인공신경망의 과적합 대응 기법입니다. <b>가지치기(Pruning)는 의사결정나무의 과적합 방지 기법</b>이므로 3번이 답입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa8","number":51,"category":"빅데이터 모델링","type":"choice","subject":"<p>의사결정나무(Decision Tree Analysis) 분석모형을 수행한 결과 뿌리노드만 남게 되는 이유로 가장 적절한 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"하위 노드를 결정할 수 있는 변별력 있는 변수가 존재하지 않아 뿌리노드에서 분류가 정지된다."},{"n":2,"html":"각 노드의 분류 기준값이 뿌리 노드의 분류 기준값과 서로 일치하지 않는다."},{"n":3,"html":"뿌리노드에서 분류 변수를 이용해 분류기준을 결정하기에는 데이터의 수가 적다."},{"n":4,"html":"하위 노드를 분류하기 위한 변수 결정값이 하위 노드에서의 결정값과 일치하지 않는다."}],"answer":[1],"explain":{"mine":"<p>뿌리노드만 남았다는 것은 첫 분할조차 일어나지 않았다는 뜻으로, <b>하위 노드를 나눌 만한 변별력 있는 변수가 없어서</b> 분류가 정지된 경우입니다(1번).</p>"}},{"id":"6a6a00571bbde79cd2c72aa3","number":52,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석에서 독립변수를 선택할 때 활용하는 방법으로 적절하지 않은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"차수 선택법(Degree Selection)"},{"n":2,"html":"단계별 선택법(Stepwise Selection)"},{"n":3,"html":"후진 제거법(Backward Elimination)"},{"n":4,"html":"전진 선택법(Forward Selection)"}],"answer":[1],"explain":{"mine":"<p>회귀분석의 변수 선택법은 <b>전진 선택법, 후진 제거법, 단계별 선택법</b>의 세 가지입니다. '차수 선택법'(1번)은 존재하지 않는 용어입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa0","number":53,"category":"빅데이터 모델링","type":"choice","subject":"<p>독립변수와 종속변수의 유형(또는 척도)에 따라 적용되는 데이터 분석방법에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"회귀분석(Regression Analysis)은 관찰된 연속형 변수들을 대상으로 두 변수 사이의 모형을 도출한 후 적합도를 측정하는 분석 방법이다."},{"n":2,"html":"로지스틱 회귀분석은 종속변수가 명목변수일 때 활용하는 회귀분석방법으로, 회귀분석과 모든 형태가 동일하며 단지 종속변수가 이항형 또는 순서적인 다항형인 경우에 사용된다."},{"n":3,"html":"교차분석(Chi-square Test)은 교차표(Cross Tabulation)를 작성하여 두 범주형 변수 사이의 연관성을 확인하는 방법이다."},{"n":4,"html":"공변량 분석(ANCOVA, Analysis of Covariance)은 종속변수가 범주형이면서 독립변수가 연속형인 경우에 사용된다."}],"answer":[4],"explain":{"mine":"<p>공변량 분석(ANCOVA)은 <b>종속변수가 연속형</b>이고 독립변수에 범주형 요인과 연속형 공변량이 함께 있는 경우에 사용합니다. '종속변수가 범주형'이라고 한 4번이 옳지 않습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aaf","number":54,"category":"빅데이터 모델링","type":"choice","subject":"<p>깊은 인공신경망을 학습할 때 나타나는 기울기 소실(Gradient Vanishing) 문제를 올바르게 설명한 것은?</p>","choices":[{"n":1,"html":"역전파 과정에서 레이어(Layer)를 다수 쌓아 데이터 표현력을 높임에 따라 학습 기울기가 커지는 현상이다."},{"n":2,"html":"역전파(Backpropagation)를 통해 데이터를 학습하는 과정에서 앞쪽 입력층 방향으로 갈수록 기울기가 점점 커져 가중치가 비정상적으로 갱신되는 현상이다."},{"n":3,"html":"활성함수의 도함수 값이 반복적으로 곱해지면서 가중치에 대한 결괏값의 기울기가 0이 되어 경사하강법을 적용할 수 없게 되는 현상이다."},{"n":4,"html":"비용함수로 쓰이는 활성함수를 최소화하는 과정에서 발생하는 가중치의 기울기가 점차 커지는 현상이다."}],"answer":[3],"explain":{"mine":"<p>기울기 소실은 역전파에서 <b>활성화 함수의 도함수(1보다 작은 값)가 반복적으로 곱해지며 기울기가 0에 가까워져</b> 앞쪽 층의 가중치가 갱신되지 않는 현상입니다(3번). 기울기가 커지는 현상은 기울기 폭주(Exploding)로 별개입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aaa","number":55,"category":"빅데이터 모델링","type":"choice","subject":"<p>연관성 분석의 측정지표 가운데, 품목 A가 들어 있는 거래 가운데 품목 A와 품목 B가 함께 들어 있는 거래가 차지하는 비율을 나타내는 지표는 무엇인가?</p>","choices":[{"n":1,"html":"정확도(Accuracy)"},{"n":2,"html":"신뢰도(Confidence)"},{"n":3,"html":"지지도(Support)"},{"n":4,"html":"향상도(Lift)"}],"answer":[2],"explain":{"mine":"<p>A를 포함한 거래 중 A와 B를 함께 포함한 거래의 비율, 즉 조건부 확률 P(B|A)는 <b>신뢰도(Confidence)</b>입니다(2번). 지지도는 전체 거래 대비 비율, 향상도는 신뢰도를 P(B)로 나눈 값입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa7","number":56,"category":"빅데이터 모델링","type":"choice","subject":"<p>로지스틱 회귀분석(Logistic Regression Analysis)에 관한 설명 중 옳은 것을 고르시오.</p>","choices":[{"n":1,"html":"종속형 변수가 맑음, 흐림, 비처럼 3개 이상의 카테고리로 나뉘는 모형에는 로지스틱 회귀분석모형을 적용할 수 없다."},{"n":2,"html":"종속변수가 범주형이고 0(음성) 또는 1(양성)로 표현되는 경우처럼 이진 분류를 수행하기 위해 사용된다."},{"n":3,"html":"로지스틱 회귀분석모형을 활용하려면 분석대상이 되는 독립변수는 반드시 이산형 변수여야 한다."},{"n":4,"html":"이진 분류에서는 두 개의 범주로 나누어지는데, 이를 위해 일반적으로 사인함수가 사용된다."}],"answer":[2],"explain":{"mine":"<p>로지스틱 회귀는 <b>종속변수가 0/1의 이진 범주일 때의 분류</b>에 사용됩니다(2번). 다항 로지스틱 회귀로 3개 이상 범주도 다룰 수 있고(1번 오답), 독립변수는 연속형도 가능하며(3번 오답), 사용하는 함수는 사인이 아니라 시그모이드입니다(4번 오답).</p>"}},{"id":"6a6a00571bbde79cd2c72aa5","number":57,"category":"빅데이터 모델링","type":"choice","subject":"<p>일반화 선형모형(GLM, Generalized Linear Model)에 관한 설명 중 옳은 것만을 모두 고르면?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 종속(반응)변수가 범주형 변수이거나 정규분포를 따르지 않는 경우에 활용된다.</li><li>(나) 종속(반응)변수가 정규분포를 따르는 경우에만 사용할 수 있다.</li><li>(다) 지정된 연결함수를 통해 종속(반응)변수가 요인 및 공변량과 선형적으로 관련되도록 선형모형을 확장한 것이다.</li><li>(라) 최소제곱 회귀분석모형과는 달리, 모형의 적합치가 최적화되는 모수를 추정할 필요가 없다.</li></ul></div>","choices":[{"n":1,"html":"(가), (나)"},{"n":2,"html":"(나), (다)"},{"n":3,"html":"(나), (라)"},{"n":4,"html":"(가), (다)"}],"answer":[4],"explain":{"mine":"<p>GLM은 (가) 종속변수가 범주형이거나 정규분포가 아닐 때 쓰이고, (다) 연결함수로 선형모형을 확장한 것입니다. (나)는 반대이고, (라)도 틀렸습니다 — GLM 역시 최대우도추정으로 모수를 추정합니다. 답은 (가), (다)인 4번입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aae","number":58,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 데이터 분석에 활용되는 ARIMA(Autoregressive Integrated Moving Average, 자기회귀 누적이동평균) 모형에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"ARIMA 모형은 Autoregression(AR) 모형과 Moving Average(MA) 모형을 결합한 모형이다."},{"n":2,"html":"ARIMA 모형에서 쓰이는 백색잡음 데이터들은 서로 독립적이지 않다."},{"n":3,"html":"현재의 시계열 값을 과거의 관측값과 오차를 이용해 설명하는 ARMA(Autoregressive Moving Average) 모형을 일반화한 모형이다."},{"n":4,"html":"시계열이 안정적이지 않은 경우 로그 변환이나 차분을 적용하여 안정적인 시계열로 만든 후 분석을 수행한다."}],"answer":[2],"explain":{"mine":"<p>백색잡음(White Noise)은 평균 0, 일정 분산에 <b>서로 독립(무상관)인</b> 오차를 말합니다. '서로 독립적이지 않다'는 2번이 옳지 않습니다. ARIMA = AR + 차분(I) + MA, 비정상 시계열의 변환·차분 처리 설명은 맞습니다.</p>"}},{"id":"6a6a00571bbde79cd2c72aa6","number":59,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 설명이 가리키는 용어로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>개별 변수를 고려하지 않은 채 전체 통계 결과를 유추하는 과정에서 발생하는 오류</li><li>부분별 평균이 크다고 하더라도 전체 평균이 반드시 큰 것은 아님</li><li>사람들의 직관에 어긋나는 상황이 나타날 때 쓰이는 표현</li></ul></div>","choices":[{"n":1,"html":"베르트랑의 역설(Bertrand Paradox)"},{"n":2,"html":"심슨의 역설(Simpson Paradox)"},{"n":3,"html":"메트칼프의 법칙(Metcalfe Law)"},{"n":4,"html":"몬티 홀 문제(Monty Hall Problem)"}],"answer":[2],"explain":{"mine":"<p>부분(집단별) 결과와 전체를 합친 결과가 반대로 나타나는 직관에 어긋나는 현상은 <b>심슨의 역설(Simpson Paradox)</b>입니다(2번). 집단별로는 A약이 우수한데 합치면 B약이 우수해 보이는 사례가 전형적입니다.</p>"}},{"id":"6a6a00571bbde79cd2c72ab1","number":60,"category":"빅데이터 모델링","type":"choice","subject":"<p>앙상블 분석모형에 관한 다음 설명 가운데 옳은 것만을 모두 고른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 단일 데이터 분석모형과 비교했을 때 분류 성능이 더 우수하다.</li><li>(나) 우수한 여러 학습 모형을 결합함으로써 예측력을 높인다.</li><li>(다) 분석모형의 결과 해석이 용이하며, 예측에 걸리는 시간이 짧다.</li><li>(라) 최종 모형의 예측값을 결정하는 방법 가운데 각 모형의 예측 확률값의 평균 또는 가중 합을 이용하는 방식을 하드 보팅(Hard Voting)이라 한다.</li></ul></div>","choices":[{"n":1,"html":"(나), (다)"},{"n":2,"html":"(나), (라)"},{"n":3,"html":"(가), (다)"},{"n":4,"html":"(가), (나)"}],"answer":[4],"explain":{"mine":"<p>(가) 앙상블은 일반적으로 단일 모형보다 분류 성능이 우수하고, (나) 여러 모형의 결합으로 예측력을 높입니다. (다)는 틀렸습니다 — 앙상블은 해석이 어렵고 예측 시간도 깁니다. (라)도 틀렸습니다 — 확률값의 평균·가중합을 쓰는 것은 <b>소프트 보팅</b>입니다. 답은 (가), (나)인 4번입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac1","number":61,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>빅데이터 분석결과를 활용하는 것에 관한 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"새로운 상품이나 서비스를 개발할 기회를 기업이 얻을 수 있다."},{"n":2,"html":"언제나 경제적 이익을 얻을 수 있다."},{"n":3,"html":"여러 대안을 비교분석함으로써 효율적인 의사결정이 가능하다."},{"n":4,"html":"효율적이고 창의적인 새로운 아이디어를 얻을 수 있다."}],"answer":[2],"explain":{"mine":"<p>빅데이터 분석이 유용하지만 '<b>언제나 경제적 이익을 얻을 수 있다</b>'는 보장은 없습니다(2번이 답). 분석 비용이 효과를 초과하거나 분석 결과가 활용되지 못하는 경우도 많습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab4","number":62,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 혼동행렬을 이용하여 계산하는 성능평가지표의 산출식 중 옳지 않은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>실제 \\ 예측 범주 값</th><th>Yes(참)</th><th>No(거짓)</th></tr><tr><td>실제 범주 값 / Yes(참)</td><td>참긍정(TP, True Positive)</td><td>가음성(FN, False Negative)</td></tr><tr><td>실제 범주 값 / No(거짓)</td><td>가양성(FP, False Positive)</td><td>참부정(TN, True Negative)</td></tr></table></div>","choices":[{"n":1,"html":"거짓긍정률(FP Rate)=FP/(TN+FP)"},{"n":2,"html":"정밀도(Precision)=TP/(TP+FP)"},{"n":3,"html":"참긍정률(TP Rate)=TP/(TP+FN)"},{"n":4,"html":"재현율(Recall)=TN/(TN+FP)"}],"answer":[4],"explain":{"mine":"<p>재현율은 <b>TP/(TP+FN)</b>입니다. 'TN/(TN+FP)'라고 쓴 4번은 특이도의 식이므로 옳지 않습니다. 거짓긍정률·정밀도·참긍정률의 식은 모두 맞습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac4","number":63,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기 가운데 비교 시각화 기법에 해당하지 않는 것은 무엇인가?</p>","choices":[{"n":1,"html":"평행 좌표 그래프(Parallel Coordinate Plot)"},{"n":2,"html":"스타 차트(Star Chart)"},{"n":3,"html":"히트맵(Heat Map)"},{"n":4,"html":"버블 차트(Bubble Chart)"}],"answer":[4],"explain":{"mine":"<p>평행 좌표 그래프, 스타 차트, 히트맵은 비교 시각화 기법입니다. <b>버블 차트는 세 변수의 관계를 보여주는 관계 시각화</b> 기법이므로 4번이 답입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac7","number":64,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 분석모형을 활용한 분석결과(머신러닝 분석결과)의 산출물에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"알고리즘 보안 계획서"},{"n":2,"html":"분석모형 유지보수 가이드"},{"n":3,"html":"효과검증 프로젝트 결과 보고서"},{"n":4,"html":"데이터 분석 계획서"}],"answer":[1],"explain":{"mine":"<p>분석결과의 산출물로는 분석 계획서, 결과 보고서, 유지보수 가이드 등이 있습니다. '<b>알고리즘 보안 계획서</b>'(1번)는 분석 결과 산출물에 해당하지 않습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72abb","number":65,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인공신경망 분석모형에 적용하는 드롭아웃(Dropout)과 같은 효과를 얻을 수 있는 기법으로 다음 중 옳은 것은?</p>","choices":[{"n":1,"html":"복잡한 분석모형 사용"},{"n":2,"html":"가중치 규제 완화"},{"n":3,"html":"학습 데이터 제거"},{"n":4,"html":"데이터 증강"}],"answer":[4],"explain":{"mine":"<p>드롭아웃은 과적합을 막는 규제 기법입니다. 같은 효과(과적합 완화)를 내는 것은 <b>데이터 증강(Data Augmentation)</b> — 학습 데이터를 변형·확장해 늘리는 방법입니다(4번). 복잡한 모형 사용이나 규제 완화는 오히려 과적합을 부추깁니다.</p>"}},{"id":"6a6a00581bbde79cd2c72abd","number":66,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 분석모형을 평가할 때 사용하는 기준으로 보기 가장 어려운 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"수집된 데이터 표본의 충분성(Sufficiency)"},{"n":2,"html":"실젯값과 예측값 간의 편향(Bias)"},{"n":3,"html":"예측값들이 가지는 분산(Variance)"},{"n":4,"html":"분류와 예측이 얼마나 정확한지를 나타내는 정확도(Accuracy)"}],"answer":[1],"explain":{"mine":"<p>분석모형 평가 기준은 정확도, 편향, 분산 등 <b>모형의 예측 품질</b>에 관한 지표입니다. '수집된 표본의 충분성'(1번)은 모형 평가가 아니라 데이터 수집 단계에서 점검할 사항입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab7","number":67,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>ROC(Receiver Operating Characteristic) 그래프에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"범주값을 분류할 때 긍정 범주와 부정 범주를 가르는 기준치가 변함에 따른 변화율을 파악할 수 있다."},{"n":2,"html":"성능평가 지표 가운데 거짓긍정률과 참긍정률을 활용해 그려진다."},{"n":3,"html":"혼동행렬은 ROC 그래프를 이용하여 구할 수 있다."},{"n":4,"html":"ROC 그래프가 대각선 형태라면 참긍정과 거짓긍정을 제대로 구별하지 못하는 것이므로 바람직하지 않은 모형으로 평가된다."}],"answer":[3],"explain":{"mine":"<p>ROC 곡선은 임곗값마다의 (FPR, TPR)을 이은 요약 곡선이라, 그래프만으로 특정 임곗값의 <b>혼동행렬을 복원할 수는 없습니다</b>(3번이 옳지 않음). 반대로 혼동행렬 하나로 ROC 위의 한 점을 찍는 것은 가능합니다. 대각선 = 무작위 분류라는 4번은 맞습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac5","number":68,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 내용이 설명하는 시각화 기법으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>전국 각 매장에서 취급하는 제품별 판매량을 나타냄</li><li>행에는 매장을, 열에는 제품을 배치</li><li>개별 셀의 판매량 값을 색상으로 표현</li></ul></div>","choices":[{"n":1,"html":"버블 차트(Bubble Chart)"},{"n":2,"html":"스타 차트(Star Chart)"},{"n":3,"html":"히트맵(Heat Map)"},{"n":4,"html":"체르노프 페이스(Chernoff Face)"}],"answer":[3],"explain":{"mine":"<p>행(매장)×열(제품)의 각 셀 값을 <b>색상의 진하기로 표현</b>하는 시각화는 <b>히트맵</b>입니다(3번).</p>"}},{"id":"6a6a00581bbde79cd2c72abf","number":69,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 분석모형을 선정하는 방법에 대한 설명으로 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"어떤 상황에서 어떤 분석모형을 적용해야 하는지에 관한 명확하고 검증된 이론이나 기준은 일반적으로 존재하지 않는다."},{"n":2,"html":"바람직한 데이터 분석모형을 선정하려면 분석 데이터 수준, 기술적 적용 수준, 분석의 전략적 중요성을 사전에 고려한다."},{"n":3,"html":"여러 가지 분석모형을 적용해 본 뒤 그중 정확도가 가장 높고 일반화 능력이 뛰어난 모형을 선택한다."},{"n":4,"html":"복잡한 분석모형은 단순한 데이터 분석모형에 비해 무조건 성능이 우수하다."}],"answer":[4],"explain":{"mine":"<p>복잡한 모형이 단순한 모형보다 '<b>무조건</b>' 우수한 것은 아닙니다 — 과적합 위험이 크고 해석이 어렵습니다(4번이 답). 상황별 정답 모형에 대한 검증된 기준이 없다는 것(1번), 여러 모형을 시도해 일반화 성능이 좋은 것을 고른다는 것(3번)은 맞습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac3","number":70,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기 가운데 관계 시각화 기법에 해당하지 않는 것은 무엇인가?</p>","choices":[{"n":1,"html":"히트맵(Heatmap)"},{"n":2,"html":"산점도(Scatter Plot)"},{"n":3,"html":"버블 차트(Bubble Chart)"},{"n":4,"html":"체르노프 페이스(Chernoff Face)"}],"answer":[4],"explain":{"mine":"<p>히트맵(상관행렬 표현)·산점도·버블 차트는 관계 시각화에 쓰입니다. <b>체르노프 페이스는 여러 변수를 얼굴 요소에 대응시키는 비교 시각화</b> 기법이므로 4번이 답입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab9","number":71,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>예측 목적의 데이터 분석모형이 얼마나 잘 수행되는지 평가하는 지표로 적절하지 않은 것은? [단, yᵢ는 실젯값(참값), ŷᵢ는 예측값을 의미한다]</p>","choices":[{"n":1,"html":"RMSE(Root Mean of Squared Errors) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><mi>n</mi></mfrac></mstyle></msqrt></mrow></semantics></math></span>"},{"n":2,"html":"MSE(Mean of Squared Errors) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">(</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></semantics></math></span>"},{"n":3,"html":"MAE(Mean of Absolute Errors) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">∣</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><mo stretchy=\"false\">∣</mo><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></semantics></math></span>"},{"n":4,"html":"MPE(Mean of Percentage Errors) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">(</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub></mrow><msub><mi>y</mi><mi>i</mi></msub></mfrac></mstyle><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">)</mo><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></semantics></math></span>"}],"answer":[4],"explain":{"mine":"<p>MPE는 양의 오차와 음의 오차가 <b>서로 상쇄</b>되어 전체 오차의 크기를 제대로 보여주지 못하므로, 예측 성능 평가 지표로는 부적절합니다(4번). 오차의 방향(과대/과소 예측 편향)을 볼 때나 쓰는 지표이며, 크기 평가에는 RMSE·MSE·MAE처럼 제곱·절댓값 기반 지표를 씁니다.</p>"}},{"id":"6a6a00581bbde79cd2c72aba","number":72,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 K-fold 교차 검증에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"전체 데이터세트를 K개의 부분집합으로 분할한 뒤, 각 부분집합을 순서대로 교차하여 검증 데이터로 활용한다."},{"n":2,"html":"데이터 집합을 체계적으로 바꿔가면서 전체 데이터에 대하여 분석모형의 성과를 측정한다."},{"n":3,"html":"훈련, 검증, 평가 데이터세트를 2:3:5의 비율로 구성한다."},{"n":4,"html":"확보한 데이터의 양이 상대적으로 적을 때 정확도를 높이기 위한 목적으로 활용한다."}],"answer":[3],"explain":{"mine":"<p>K-fold 교차검증은 데이터를 K개 부분으로 나눠 교차 사용하는 방식이지, '<b>훈련:검증:평가 = 2:3:5</b>' 같은 고정 비율 분할과는 무관합니다(3번이 옳지 않음). 데이터가 적을 때 유용하다는 4번은 맞습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72abe","number":73,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 마이닝 기법의 하나로, 과거 데이터와 향후 상황에 대한 가정을 바탕으로 고객이 특정 제품을 구매하거나 제안에 반응할 확률과 같은 비즈니스 활동의 결과를 미리 추정하는 분석 방법은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"Clustering Analysis"},{"n":2,"html":"Propagation Analysis"},{"n":3,"html":"Predictive Analysis"},{"n":4,"html":"Association Analysis"}],"answer":[3],"explain":{"mine":"<p>과거 데이터와 가정을 바탕으로 구매 확률 같은 <b>미래 비즈니스 결과를 추정</b>하는 분석은 <b>예측 분석(Predictive Analysis)</b>입니다(3번).</p>"}},{"id":"6a6a00581bbde79cd2c72ab5","number":74,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래의 혼동행렬이 주어졌을 때, 재현율을 구하는 공식으로 알맞은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>실제 \\ 예측 범주 값</th><th>Yes(참)</th><th>No(거짓)</th></tr><tr><td>실제 범주 값 / Yes(참)</td><td>참긍정(TP, True Positive)</td><td>가음성(FN, False Negative)</td></tr><tr><td>실제 범주 값 / No(거짓)</td><td>가양성(FP, False Positive)</td><td>참부정(TN, True Negative)</td></tr></table></div>","choices":[{"n":1,"html":"FP/(TN+FP)"},{"n":2,"html":"TN/(TN+FP)"},{"n":3,"html":"TP/(TP+FP)"},{"n":4,"html":"TP/(TP+FN)"}],"answer":[4],"explain":{"mine":"<p>재현율(Recall)은 실제 긍정 가운데 긍정으로 맞게 예측한 비율 = <b>TP/(TP+FN)</b>입니다(4번). 민감도·참긍정률(TPR)과 같은 지표입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac2","number":75,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>분석 결과를 시각화할 때 거치는 주요 프로세스에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"정제"},{"n":2,"html":"시각화"},{"n":3,"html":"구조화"},{"n":4,"html":"시각표현"}],"answer":[1],"explain":{"mine":"<p>분석 결과 시각화의 주요 프로세스는 <b>구조화 → 시각화 → 시각표현</b>의 3단계입니다. '정제'(1번)는 시각화 프로세스가 아니라 데이터 전처리 단계의 작업입니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab8","number":76,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>ROC(Receiver Operating Characteristic) 곡선을 그릴 때 두 축에 사용되는 지표를 바르게 나열한 것은 무엇인가?</p>","choices":[{"n":1,"html":"특이도, 정밀도"},{"n":2,"html":"특이도, 정확도"},{"n":3,"html":"민감도, 정밀도"},{"n":4,"html":"민감도, 특이도"}],"answer":[4],"explain":{"mine":"<p>ROC 곡선의 y축은 <b>민감도(TPR)</b>, x축은 1−특이도(FPR)이므로 두 축에 사용되는 지표는 <b>민감도와 특이도</b>입니다(4번).</p>"}},{"id":"6a6a00581bbde79cd2c72ac0","number":77,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>분석 결과를 스토리텔링(Storytelling)으로 전달할 때 수행하는 업무에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"스토리보드의 기획"},{"n":2,"html":"사용자별로 데이터세트와 정보를 정의"},{"n":3,"html":"사용자 시나리오의 작성"},{"n":4,"html":"스토리보드 도구 검증"}],"answer":[4],"explain":{"mine":"<p>스토리텔링 전달 업무는 스토리보드 기획, 사용자별 데이터·정보 정의, 사용자 시나리오 작성입니다. '<b>스토리보드 도구 검증</b>'(4번)은 여기에 해당하지 않습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ac6","number":78,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 인포그래픽(Infographics)에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"차트, 지도, 다이어그램, 로고, 일러스트레이터 등을 활용하여 시각적 형태로 전달한다."},{"n":2,"html":"시각화된 정보는 이해하기 쉽고 오래 기억되며, 인터넷 등을 통해 자발적으로 퍼지는 확산 효과가 있다."},{"n":3,"html":"효율적으로 많은 정보를 나타낼 수 있다."},{"n":4,"html":"분석대상의 각각의 변수들에 대한 패턴을 효율적으로 발견할 수 있다."}],"answer":[4],"explain":{"mine":"<p>인포그래픽은 정보의 요약·전달이 목적입니다. <b>개별 변수들의 패턴을 발견하는 것은 데이터 시각화(탐색적 분석)의 역할</b>이므로 4번이 적절하지 않습니다. 확산 효과, 효율적 정보 전달 설명은 맞습니다.</p>"}},{"id":"6a6a00581bbde79cd2c72ab6","number":79,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>어떤 분류 모델의 정밀도(Precision)가 40%, 재현율(Recall)이 60%로 측정되었다. 이때 F1-Score(F-Measure)를 구하면?</p>","choices":[{"n":1,"html":"47%"},{"n":2,"html":"48%"},{"n":3,"html":"49%"},{"n":4,"html":"50%"}],"answer":[2],"explain":{"mine":"<p>F1 = 2 × 정밀도 × 재현율 ÷ (정밀도 + 재현율) = 2 × 0.4 × 0.6 ÷ 1.0 = <b>0.48 (48%)</b>입니다(2번). 산술평균(50%)이 아니라 조화평균이라 더 낮게 나옵니다.</p>"}},{"id":"6a6a00581bbde79cd2c72abc","number":80,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>과대적합에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"과대적합이 발생하면 데이터 분석모형의 파라미터 수가 많아 주어진 데이터에 대해 다소 복잡한 모형이 만들어진다."},{"n":2,"html":"머신러닝에서 과대적합은 흔히 나타나는 현상이며, 분석모형이 과대적합된 경우 일반적으로 분산이 크게 나타난다."},{"n":3,"html":"과대적합은 선형모형에서 비선형모형보다 더 쉽게 발생한다."},{"n":4,"html":"훈련 데이터세트에서는 평가 점수가 좋았으나 테스트 데이터세트에서 점수가 매우 나쁘다면, 훈련 데이터세트에 과대적합된 것이라고 한다."}],"answer":[3],"explain":{"mine":"<p>과대적합은 파라미터가 많은 <b>복잡한 비선형 모형에서 더 쉽게 발생</b>합니다. '선형모형에서 더 쉽게 발생한다'는 3번이 옳지 않습니다. 과대적합 시 분산이 커지고, 훈련 성능 대비 평가 성능이 크게 나쁘다는 설명은 맞습니다.</p>"}}]};